#include <stdio.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("INVALID_INPUT\n");
        return 0;
    }
    char *tape = argv[1];
    size_t tape_len = strlen(tape);
    int steps = 0;
    int pos = 0;
    while (pos < tape_len) {
        if (tape[pos] == '0') {
            tape[pos] = '1';
            pos++;
        } else if (tape[pos] == '1') {
            tape[pos] = '0';
            pos--;
        }
        steps++;
    }
    printf("result=");
    for (int i = 0; i < tape_len; i++) {
        putchar(tape[i]);
    }
    printf("\nsteps=%d\n", steps);
    return 0;
}
